      "WmapigwMigrationResponse": {
        "type": "object",
        "description": "Response from the WMAPIGW migration API.",
        "properties": {
          "jobId": {
            "type": "string",
            "description": "Identifier for the migration job",
            "example": "migration-job-wmapigw"
          },
          "status": {
            "type": "string",
            "description": "Status of the migration operation",
            "example": "INITIATED"
          },
          "createdAt": {
            "type": "string",
            "format": "date-time",
            "description": "Time when the migration job was created"
          },
          "retryOf": {
            "type": "string",
            "description": "Original job ID if this is a retry operation",
            "example": "migration-job-wmapigw"
          }
        }
      },
      "MigrationRequest": {
        "type": "object",
        "description": "A migration is created",
        "properties": {
          "endpoint": {
            "type": "string",
            "description": "The endpoint URL of the remote OpenSearch instance"
          },
          "username": {
            "type": "string",
            "description": "Username for basic authentication"
          },
          "password": {
            "type": "string",
            "description": "Password for basic authentication"
          },
          "endpoint_ca": {
            "type": "string",
            "description": "Base64 encoded CA certificate for SSL verification. Only used if disable_tls_validation is undefined or false. Should be provided together with endpoint_client_cert and endpoint_client_key."
          },
          "endpoint_client_cert": {
            "type": "string",
            "description": "Base64 encoded client certificate for certificate-based authentication. Only used if disable_tls_validation is undefined or false. Should be provided together with endpoint_ca and endpoint_client_key."
          },
          "endpoint_client_key": {
            "type": "string",
            "description": "Base64 encoded client key for certificate-based authentication. Only used if disable_tls_validation is undefined or false. Should be provided together with endpoint_ca and endpoint_client_cert."
          },
          "startTime": {
            "type": "string",
            "format": "date-time",
            "description": "Start time for data migration"
          },
          "endTime": {
            "type": "string",
            "format": "date-time",
            "description": "End time for data migration"
          },
          "gateway_service_name": {
            "type": "string",
            "description": "Name of the gateway service to migrate data from"
          },
          "disable_tls_validation": {
            "type": "boolean",
            "description": "Whether to disable TLS certificate validation when connecting to the endpoint, by default the value is set to false"
          }
        },
        "required": [
          "endpoint",
          "gateway_service_name"
        ]
      },
      "WmapigwMigrationStatusResponse": {
        "type": "object",
        "description": "Response from the WMAPIGW migration status API.",
        "properties": {
          "jobId": {
            "type": "string",
            "description": "Identifier for the migration job",
            "example": "migration-job-wmapigw"
          },
          "status": {
            "type": "string",
            "description": "Current status of the migration operation",
            "example": "PROCESSING"
          },
          "createdAt": {
            "type": "string",
            "format": "date-time",
            "description": "Time when the migration job was created"
          },
          "updatedAt": {
            "type": "string",
            "format": "date-time",
            "description": "Time when the migration job was last updated"
          },
          "progress": {
            "type": "number",
            "description": "Percentage of migration completed",
            "minimum": 0,
            "maximum": 100,
            "example": 65
          },
          "totalIndices": {
            "type": "number",
            "description": "Total number of indices to be migrated",
            "example": 10
          },
          "completedIndices": {
            "type": "number",
            "description": "Number of indices that have been successfully migrated",
            "example": 6
          },
          "failedIndices": {
            "type": "number",
            "description": "Number of indices that failed to migrate",
            "example": 1
          },
          "currentIndex": {
            "type": "string",
            "description": "Name of the index currently being migrated",
            "example": "apic-events-2025.01"
          },
          "processedDocs": {
            "type": "number",
            "description": "Number of documents that have been processed",
            "example": 15000
          },
          "skippedDocs": {
            "type": "number",
            "description": "Number of documents that were skipped during migration",
            "example": 50
          },
          "error": {
            "type": "string",
            "description": "Error message if migration failed",
            "example": "Failed to connect to source database"
          },
          "canRetry": {
            "type": "boolean",
            "description": "Whether the migration can be retried",
            "example": true
          }
        }
      },
      "WmMigrationRequest": {
        "description": "Request object to create a migration",
        "$ref": "#/components/schemas/MigrationRequest"
      },
